// HSK 4–6 场景课程。课程文本、练习与例句为青禾中文原创。
function makeUpperLesson(s){
  return {
    id:s.id,level:s.level,title:s.title,scene:s.scene,vocab:s.vocab,
    dialogue:s.dialogue.map(line=>{const cut=line.indexOf('|');return{s:line.slice(0,cut),t:line.slice(cut+1)}}),
    grammar:{name:s.grammar.name,pattern:s.grammar.pattern,explain:s.grammar.explain,examples:s.grammar.examples,practice:{q:'哪一句更符合“'+s.grammar.name+'”的用法？',opts:[s.grammar.examples[0],s.grammar.wrong],ans:0}},
    listening:s.listening,shadowing:s.shadowing,quiz:s.quiz
  };
}

const upperLessons=[
  makeUpperLesson({id:'QH-031',level:'HSK 4',title:'我已经把文件发给你了',scene:'确认工作进度',vocab:['文件','发送','确认','附件','及时','负责','进度','收到'],dialogue:['林|你负责的那份文件准备好了吗？','安|准备好了，我已经把文件发给你了。','林|我刚看到邮件，不过好像没有附件。','安|抱歉，我马上重新发送，请你收到后确认一下。','林|没问题，谢谢你处理得这么及时。'],grammar:{name:'“把”字句与结果',pattern:'主语 + 把 + 宾语 + 动词 + 结果',explain:'“把”字句突出某个对象经过动作后产生的变化或结果。',examples:['我已经把文件发给你了。','请把附件重新发送一次。'],wrong:'我已经文件把发给你了。'},listening:{q:'文件出现了什么问题？',audio:'我刚看到邮件，不过好像没有附件。',opts:['文件没有写完','邮件没有附件','对方没有邮箱'],ans:1},shadowing:'我已经把文件发给你了，请你收到后确认一下。',quiz:{q:'请 ___ 附件重新发送一次。',opts:['把','被','由'],ans:0,fb:'突出“附件”经过重新发送，用“把”。'}}),
  makeUpperLesson({id:'QH-032',level:'HSK 4',title:'这家店既便宜又好吃',scene:'推荐一家餐厅',vocab:['推荐','味道','价格','环境','既然','排队','值得','附近'],dialogue:['安|附近有没有值得推荐的餐厅？','林|有一家小店既便宜又好吃，环境也很舒服。','安|听起来不错，需要提前订位吗？','林|不用，不过晚饭时间常常要排队。','安|既然大家都喜欢，我们早点儿去吧。'],grammar:{name:'既……又……',pattern:'既 + 特点一 + 又 + 特点二',explain:'“既……又……”把两个并列的特点放在一起说明。',examples:['这家店既便宜又好吃。','她既认真又有耐心。'],wrong:'这家店既便宜但是好吃。'},listening:{q:'这家店晚饭时间怎么样？',audio:'不用订位，不过晚饭时间常常要排队。',opts:['常常排队','没有客人','只卖午饭'],ans:0},shadowing:'这家店既便宜又好吃，虽然要排队，但是很值得。',quiz:{q:'她 ___ 认真 ___ 有耐心。',opts:['既；又','因为；所以','虽然；但是'],ans:0,fb:'两个并列优点用“既……又……”。'}}),
  makeUpperLesson({id:'QH-033',level:'HSK 4',title:'只要坚持，就会看到进步',scene:'讨论学习方法',vocab:['坚持','方法','效果','目标','放弃','积累','习惯','明显'],dialogue:['林|我每天都背单词，为什么进步还是不明显？','安|学习语言需要积累，不能只看一天的效果。','林|可是有时候我真想放弃。','安|只要坚持使用适合自己的方法，就会慢慢看到进步。','林|那我先把目标改成每天学习二十分钟。'],grammar:{name:'只要……就……',pattern:'只要 + 条件，就 + 结果',explain:'“只要……就……”说明一个足以带来结果的条件。',examples:['只要坚持，就会看到进步。','只要提前准备，就不会太紧张。'],wrong:'只要坚持，但是会看到进步。'},listening:{q:'林决定怎样调整目标？',audio:'那我先把目标改成每天学习二十分钟。',opts:['每天学习二十分钟','每天学习两个小时','暂时停止学习'],ans:0},shadowing:'只要坚持使用适合自己的方法，就会慢慢看到进步。',quiz:{q:'___ 提前准备，___ 不会太紧张。',opts:['只要；就','即使；也','不但；而且'],ans:0,fb:'条件足够时用“只要……就……”。'}}),
  makeUpperLesson({id:'QH-034',level:'HSK 4',title:'原来他已经搬家了',scene:'发现情况发生变化',vocab:['原来','搬家','联系','地址','邻居','消息','熟悉','偶然'],dialogue:['安|我昨天去找老周，发现门口已经换了名字。','林|原来他已经搬家了，你不知道吗？','安|我最近没和他联系，完全没听说这个消息。','林|他搬到地铁站附近了，新地址我发给你。','安|难怪最近在小区里一直没见到他。'],grammar:{name:'原来；难怪',pattern:'原来 + 新发现。难怪 + 已知结果。',explain:'“原来”引出后来才知道的事实；“难怪”表示原因明白后不再觉得奇怪。',examples:['原来他已经搬家了。','难怪最近一直没见到他。'],wrong:'虽然他已经搬家了，难怪我不知道。'},listening:{q:'安为什么不知道老周搬家？',audio:'我最近没和他联系，完全没听说这个消息。',opts:['没有联系方式','最近没有联系','地址写错了'],ans:1},shadowing:'原来他已经搬家了，难怪最近一直没见到他。',quiz:{q:'___ 你今天没来上课，___ 你生病了。',opts:['难怪；原来','只要；就','因为；但是'],ans:0,fb:'先说不奇怪，再说明后来知道的原因。'}}),
  makeUpperLesson({id:'QH-035',level:'HSK 4',title:'这次活动由我们部门负责',scene:'分配团队任务',vocab:['部门','负责','安排','场地','宣传','预算','合作','顺利'],dialogue:['林|下个月的文化活动由哪个部门负责？','安|这次活动由我们部门负责，场地已经安排好了。','林|宣传和预算也由你们处理吗？','安|宣传会和市场部合作，预算需要经理确认。','林|分工清楚，活动一定会很顺利。'],grammar:{name:'由……负责 / 由……来……',pattern:'事情 + 由 + 人或部门 + 负责/来完成',explain:'“由”引出动作或任务的承担者，常用于正式分工。',examples:['这次活动由我们部门负责。','最后的报告由小王来完成。'],wrong:'这次活动把我们部门负责。'},listening:{q:'谁负责宣传？',audio:'宣传会和市场部合作，预算需要经理确认。',opts:['只由经理负责','部门与市场部合作','由场地负责人处理'],ans:1},shadowing:'这次活动由我们部门负责，宣传会和市场部合作。',quiz:{q:'最后的报告 ___ 小王来完成。',opts:['由','把','被'],ans:0,fb:'引出任务承担者时用“由”。'}}),
  makeUpperLesson({id:'QH-036',level:'HSK 4',title:'别看天气冷，公园里人可不少',scene:'描述出乎意料的情况',vocab:['别看','热闹','锻炼','散步','精神','温度','适合','尤其'],dialogue:['安|今天这么冷，公园里应该没什么人吧？','林|别看天气冷，公园里人可不少。','安|大家都在做什么？','林|有人跑步，有人散步，老人尤其喜欢早上锻炼。','安|看来只要穿得暖一点，冬天也适合运动。'],grammar:{name:'别看……，可是/却……',pattern:'别看 + 表面情况，实际结果却……',explain:'“别看”提醒听者不要只根据表面情况判断，后面常出现意外结果。',examples:['别看天气冷，公园里人可不少。','别看他话不多，想法却很丰富。'],wrong:'别看天气冷，所以公园里没人。'},listening:{q:'公园里的人主要做什么？',audio:'有人跑步，有人散步，老人尤其喜欢早上锻炼。',opts:['等公共汽车','跑步和散步','参加比赛'],ans:1},shadowing:'别看天气冷，公园里人可不少，大家都很有精神。',quiz:{q:'别看他话不多，想法 ___ 很丰富。',opts:['却','所以','因为'],ans:0,fb:'表面和实际相反时常用“却”。'}}),
  makeUpperLesson({id:'QH-037',level:'HSK 4',title:'我对这个决定有点犹豫',scene:'表达态度和顾虑',vocab:['决定','犹豫','机会','风险','考虑','建议','接受','后悔'],dialogue:['林|公司给你去外地工作的机会，你决定了吗？','安|我对这个决定还有点犹豫。','林|你主要担心什么？','安|机会很好，但生活变化也很大，我需要认真考虑风险。','林|别急，听听家人的建议再决定也不晚。'],grammar:{name:'对……感到 / 对……有……',pattern:'主语 + 对 + 对象 + 感到/有 + 态度或情绪',explain:'用“对”引出态度、情绪或看法所针对的对象。',examples:['我对这个决定有点犹豫。','大家对结果感到满意。'],wrong:'我把这个决定有点犹豫。'},listening:{q:'安为什么犹豫？',audio:'机会很好，但生活变化也很大，我需要认真考虑风险。',opts:['工作没有工资','生活变化和风险较大','家人不同意'],ans:1},shadowing:'这个机会很好，但我对生活变化还有点犹豫。',quiz:{q:'大家 ___ 结果感到满意。',opts:['对','把','从'],ans:0,fb:'态度针对某个对象时用“对”。'}}),
  makeUpperLesson({id:'QH-038',level:'HSK 4',title:'不仅要会说，还要会解释',scene:'提高表达能力',vocab:['不仅','解释','准确','表达','误会','观点','词汇','交流'],dialogue:['安|我认识很多词，可是一讨论复杂问题就说不清楚。','林|学语言不仅要会说，还要会解释自己的观点。','安|怎样才能表达得更准确？','林|先说结论，再说明理由，还可以举一个例子。','安|这样能减少误会，也更容易交流。'],grammar:{name:'不仅……还/而且……',pattern:'不仅 + 内容一，还/而且 + 内容二',explain:'“不仅……还……”表示后一个内容在前一个基础上进一步增加。',examples:['不仅要会说，还要会解释。','这本书不仅有意思，而且很实用。'],wrong:'不仅要会说，但是要会解释。'},listening:{q:'林建议怎样组织观点？',audio:'先说结论，再说明理由，还可以举一个例子。',opts:['先举例再忘记结论','先说结论再说明理由','只使用简单词汇'],ans:1},shadowing:'学语言不仅要会说，还要会准确地解释自己的观点。',quiz:{q:'这本书不仅有意思，___ 很实用。',opts:['而且','可是','因此'],ans:0,fb:'递进增加信息用“而且”。'}}),
  makeUpperLesson({id:'QH-039',level:'HSK 4',title:'这次旅行比预想顺利得多',scene:'比较预期和实际',vocab:['预想','顺利','行程','提前','交通','经验','省心','临时'],dialogue:['林|听说你刚旅行回来，行程怎么样？','安|这次旅行比预想顺利得多。','林|交通和住宿都没出问题吗？','安|我提前做了计划，只有一天临时下雨，其他都很省心。','林|有了这次经验，下次安排起来会更轻松。'],grammar:{name:'比……形容词得多',pattern:'A + 比 + B + 形容词 + 得多/一点儿',explain:'在比较句后加“得多”或“一点儿”，说明差异的程度。',examples:['这次旅行比预想顺利得多。','今天比昨天暖和一点儿。'],wrong:'这次旅行比较预想顺利很多。'},listening:{q:'旅行为什么比较顺利？',audio:'我提前做了计划，只有一天临时下雨。',opts:['完全没有计划','提前做了计划','每天都下雨'],ans:1},shadowing:'这次旅行比预想顺利得多，提前计划真的很重要。',quiz:{q:'今天比昨天暖和 ___ 。',opts:['一点儿','一些地','了得'],ans:0,fb:'比较差异较小时可以说“一点儿”。'}}),
  makeUpperLesson({id:'QH-040',level:'HSK 4',title:'问题终于得到了解决',scene:'总结处理结果',vocab:['解决','影响','设备','恢复','技术','检查','原因','正常'],dialogue:['安|昨天系统出了问题，影响了不少客户。','林|现在恢复正常了吗？','安|技术人员检查了一整晚，问题终于得到了解决。','林|找到原因了吗？','安|是设备设置错误，我们已经修改，也增加了检查步骤。'],grammar:{name:'得到 + 抽象结果',pattern:'问题/要求/意见 + 得到 + 解决/满足/重视',explain:'“得到”后接抽象结果，常用于较正式的书面或工作表达。',examples:['问题终于得到了解决。','这个建议得到了大家的重视。'],wrong:'问题终于得了解决到。'},listening:{q:'问题的原因是什么？',audio:'是设备设置错误，我们已经修改，也增加了检查步骤。',opts:['客户操作错误','设备设置错误','网络完全中断'],ans:1},shadowing:'问题终于得到了解决，系统也恢复了正常。',quiz:{q:'这个建议得到大家的 ___ 。',opts:['重视','重量','重新'],ans:0,fb:'正式表达中常说“得到重视”。'}}),

  makeUpperLesson({id:'QH-041',level:'HSK 5',title:'换个角度看问题',scene:'讨论解决思路',vocab:['角度','现象','忽略','立场','重新','分析','矛盾','限制'],dialogue:['林|这个方案的问题越来越多，我觉得应该放弃。','安|先别急，也许我们可以换个角度看问题。','林|你的意思是重新分析用户的需求？','安|对。站在用户的立场上，原来的限制可能正是机会。','林|看来我们忽略了现象背后的原因。'],grammar:{name:'从……角度来看',pattern:'从 + 角度/立场 + 来看，观点',explain:'这一结构先限定观察问题的角度，再提出判断，适合讨论和论证。',examples:['从用户的角度来看，这个步骤太复杂。','从长期来看，这项投入很有价值。'],wrong:'从用户来看角度，这个步骤太复杂。'},listening:{q:'安建议从谁的立场分析？',audio:'站在用户的立场上，原来的限制可能正是机会。',opts:['用户','竞争对手','经理'],ans:0},shadowing:'从用户的角度来看，原来的限制也可能是新的机会。',quiz:{q:'___ 长期来看，这项投入很有价值。',opts:['从','把','由'],ans:0,fb:'限定观察角度时用“从……来看”。'}}),
  makeUpperLesson({id:'QH-042',level:'HSK 5',title:'这项规定引起了广泛讨论',scene:'概述公共议题',vocab:['规定','引起','广泛','讨论','实施','反映','意见','调整'],dialogue:['安|新的交通规定下个月就要实施了。','林|我看到这项规定引起了广泛讨论。','安|支持的人认为能减少拥堵，反对的人担心不够方便。','林|有关部门正在收集意见，可能还会调整。','安|先了解不同人的实际情况再决定更合理。'],grammar:{name:'引起 / 导致 / 造成',pattern:'原因 + 引起/导致/造成 + 结果',explain:'三者都连接原因和结果；“引起”常接关注或讨论，“导致/造成”常接后果。',examples:['这项规定引起了广泛讨论。','连续降雨导致部分道路关闭。'],wrong:'这项规定发生了大家讨论。'},listening:{q:'有关部门正在做什么？',audio:'有关部门正在收集意见，可能还会调整。',opts:['取消所有规定','收集意见','立即处罚'],ans:1},shadowing:'这项规定引起了广泛讨论，有关部门正在收集意见。',quiz:{q:'连续降雨 ___ 部分道路关闭。',opts:['导致','引起到','受到'],ans:0,fb:'原因带来具体后果，可以用“导致”。'}}),
  makeUpperLesson({id:'QH-043',level:'HSK 5',title:'即使失败，也值得尝试',scene:'评估挑战与价值',vocab:['即使','失败','尝试','值得','挑战','收获','勇气','经验'],dialogue:['林|这个项目成功的可能性不高，你还想参加吗？','安|想。即使最后失败，也值得尝试。','林|你不担心浪费时间？','安|过程中获得的经验和收获，本身就很有价值。','林|有这样的勇气，结果已经不是唯一目标了。'],grammar:{name:'即使……也……',pattern:'即使 + 假设情况，也 + 不变的结果',explain:'“即使……也……”表示前面的情况不会改变后面的选择或结论。',examples:['即使失败，也值得尝试。','即使很忙，他也会坚持阅读。'],wrong:'即使失败，所以值得尝试。'},listening:{q:'安为什么愿意参加？',audio:'过程中获得的经验和收获，本身就很有价值。',opts:['项目一定成功','经验本身有价值','完全不用花时间'],ans:1},shadowing:'即使最后失败，这段经历也一定会给我带来收获。',quiz:{q:'即使很忙，他 ___ 会坚持阅读。',opts:['也','才','却不'],ans:0,fb:'假设条件不改变结果，用“也”。'}}),
  makeUpperLesson({id:'QH-044',level:'HSK 5',title:'与其等待，不如先行动',scene:'比较两种选择',vocab:['与其','等待','行动','主动','机会','犹豫','掌握','至少'],dialogue:['安|我想等条件完全准备好以后再开始。','林|可是什么时候才算完全准备好呢？','安|我只是担心做错。','林|与其一直等待，不如先行动，至少能发现真正的问题。','安|你说得对，机会往往是在行动中掌握的。'],grammar:{name:'与其……不如……',pattern:'与其 + 不理想选择，不如 + 更好选择',explain:'这一结构比较两个选择，并明确推荐后一个。',examples:['与其一直等待，不如先行动。','与其抱怨，不如想办法解决。'],wrong:'与其一直等待，所以先行动。'},listening:{q:'林建议安怎么做？',audio:'与其一直等待，不如先行动，至少能发现真正的问题。',opts:['继续等待','先开始行动','放弃机会'],ans:1},shadowing:'与其等所有条件都完美，不如先行动起来。',quiz:{q:'与其抱怨，___ 想办法解决。',opts:['不如','虽然','不但'],ans:0,fb:'比较并推荐后一个选择，用“不如”。'}}),
  makeUpperLesson({id:'QH-045',level:'HSK 5',title:'调查结果表明，需求正在变化',scene:'汇报调查结果',vocab:['调查','表明','需求','趋势','数据','比例','增长','用户'],dialogue:['林|这次用户调查有什么新发现？','安|调查结果表明，用户对移动学习的需求正在增长。','林|变化明显吗？','安|很明显。每天使用手机学习的人数比例提高了近一倍。','林|那产品设计也应该根据这个趋势进行调整。'],grammar:{name:'结果表明 / 数据显示',pattern:'调查结果/数据 + 表明/显示 + 结论',explain:'用数据或调查支持结论时，常用“表明、显示、说明”等正式表达。',examples:['调查结果表明，需求正在变化。','数据显示，使用人数持续增长。'],wrong:'调查结果觉得需求正在变化。'},listening:{q:'哪类学习需求正在增长？',audio:'用户对移动学习的需求正在增长。',opts:['移动学习','纸质考试','线下住宿'],ans:0},shadowing:'调查结果表明，用户的学习需求正在发生明显变化。',quiz:{q:'数据 ___ ，使用人数持续增长。',opts:['显示','表现着','看见'],ans:0,fb:'数据支持结论时常说“数据显示”。'}}),
  makeUpperLesson({id:'QH-046',level:'HSK 5',title:'我逐渐适应了新的生活节奏',scene:'描述适应过程',vocab:['逐渐','适应','节奏','陌生','压力','规律','调整','状态'],dialogue:['安|搬到新城市以后，你生活得怎么样？','林|刚开始很不习惯，不过我逐渐适应了新的生活节奏。','安|最大的变化是什么？','林|以前压力很大，现在作息更规律，也认识了不少朋友。','安|看来状态变好需要时间，也需要主动调整。'],grammar:{name:'逐渐 / 渐渐',pattern:'主语 + 逐渐/渐渐 + 发生变化',explain:'“逐渐”强调变化经过一个过程，书面语中使用更频繁。',examples:['我逐渐适应了新的生活节奏。','大家渐渐理解了他的选择。'],wrong:'我逐渐马上适应了新的节奏。'},listening:{q:'林现在的生活有哪些变化？',audio:'现在作息更规律，也认识了不少朋友。',opts:['压力更大了','作息更规律了','仍然不认识人'],ans:1},shadowing:'经过一段时间，我逐渐适应了新的生活节奏。',quiz:{q:'大家 ___ 理解了他的选择。',opts:['渐渐','立刻逐渐','突然慢慢'],ans:0,fb:'变化经过过程，可以用“渐渐”。'}}),
  makeUpperLesson({id:'QH-047',level:'HSK 5',title:'这本书给我留下了深刻印象',scene:'分享阅读感受',vocab:['留下','深刻','印象','描写','人物','情节','真实','思考'],dialogue:['林|最近读的书里，哪一本最打动你？','安|《山里的来信》给我留下了很深的印象。','林|是情节特别精彩吗？','安|情节并不复杂，但人物描写很真实，让我思考了很久。','林|能让人继续思考的作品往往更有力量。'],grammar:{name:'给……留下……印象',pattern:'事物 + 给 + 人 + 留下 + 程度 + 印象',explain:'用这一结构说明某件事物对人的长期感受或影响。',examples:['这本书给我留下了深刻印象。','这座城市给游客留下了美好的印象。'],wrong:'这本书把我留下了深刻印象。'},listening:{q:'安为什么喜欢这本书？',audio:'情节并不复杂，但人物描写很真实，让我思考了很久。',opts:['价格很便宜','人物描写真实','故事非常短'],ans:1},shadowing:'这本书的人物描写很真实，给我留下了深刻印象。',quiz:{q:'这座城市给游客留下了 ___ 的印象。',opts:['美好','美好地','美好了'],ans:0,fb:'“印象”前用形容词“美好”。'}}),
  makeUpperLesson({id:'QH-048',level:'HSK 5',title:'能否成功取决于准备是否充分',scene:'分析成功条件',vocab:['取决于','充分','条件','资源','能力','执行','计划','能否'],dialogue:['安|你觉得这个项目一定会成功吗？','林|现在还很难判断，能否成功取决于准备是否充分。','安|我们已经有计划和资源了。','林|还要看团队的执行能力，以及遇到变化时能不能及时调整。','安|看来成功不是只由一个条件决定的。'],grammar:{name:'取决于；能否……是否……',pattern:'结果 + 取决于 + 条件是否成立',explain:'“取决于”说明决定结果的关键因素；“能否/是否”用于不确定的两种可能。',examples:['能否成功取决于准备是否充分。','效果取决于计划能不能落实。'],wrong:'能否成功取决准备充分。'},listening:{q:'除了计划和资源，还要看什么？',audio:'还要看团队的执行能力，以及遇到变化时能不能及时调整。',opts:['办公地点','执行与调整能力','项目名称'],ans:1},shadowing:'项目能否成功，取决于准备是否充分和执行是否到位。',quiz:{q:'学习效果取决于计划能不能 ___ 。',opts:['落实','落后','落下'],ans:0,fb:'计划被实际执行，常说“落实计划”。'}}),
  makeUpperLesson({id:'QH-049',level:'HSK 5',title:'我们有必要重新考虑这个方案',scene:'提出正式建议',vocab:['必要','重新','方案','成本','长期','短期','可行','评估'],dialogue:['林|这个方案能在一个月内上线，速度很快。','安|但长期成本比预计高得多，我们有必要重新考虑。','林|你担心方案不可行吗？','安|短期可行不等于长期合适，最好再做一次全面评估。','林|同意，速度和成本都应该考虑。'],grammar:{name:'有必要 / 没必要',pattern:'主语 + 有必要/没必要 + 动词',explain:'用“有必要”正式说明某个行动值得或需要进行。',examples:['我们有必要重新考虑这个方案。','你没必要为小错误过分担心。'],wrong:'我们有必要了重新考虑这个方案。'},listening:{q:'为什么需要重新考虑方案？',audio:'长期成本比预计高得多，最好再做一次全面评估。',opts:['上线速度太慢','长期成本较高','团队完全不同意'],ans:1},shadowing:'短期可行不等于长期合适，我们有必要重新评估。',quiz:{q:'你 ___ 为一个小错误过分担心。',opts:['没必要','没必须','不必要了'],ans:0,fb:'表示无需做某事，可以说“没必要”。'}}),
  makeUpperLesson({id:'QH-050',level:'HSK 5',title:'他之所以进步，是因为一直坚持',scene:'解释深层原因',vocab:['之所以','进步','坚持','天赋','过程','付出','原因','成果'],dialogue:['安|大家都说小周很有语言天赋。','林|天赋可能有影响，但他之所以进步快，是因为一直坚持练习。','安|他每天都练吗？','林|对，而且每次都会记录问题，再找老师请教。','安|看来成果背后往往有我们看不到的付出。'],grammar:{name:'之所以……是因为……',pattern:'之所以 + 结果，是因为 + 原因',explain:'这一结构先提出需要解释的结果，再强调真正的原因。',examples:['他之所以进步快，是因为一直坚持。','我之所以选择这里，是因为环境安静。'],wrong:'他之所以进步快，所以一直坚持。'},listening:{q:'小周每次练习后会做什么？',audio:'每次都会记录问题，再找老师请教。',opts:['马上休息','记录问题并请教','只背新单词'],ans:1},shadowing:'他之所以进步快，不只是因为天赋，更因为长期坚持。',quiz:{q:'我之所以选择这里，___ 环境很安静。',opts:['是因为','所以','即使'],ans:0,fb:'“之所以”常与“是因为”呼应。'}}),

  makeUpperLesson({id:'QH-051',level:'HSK 6',title:'人工智能如何改变学习',scene:'讨论技术与教育',vocab:['人工智能','个性化','取代','辅助','效率','判断','伦理','依赖'],dialogue:['林|有人认为人工智能会取代传统课堂，你怎么看？','安|它更可能改变学习方式，而不是简单取代老师。','林|比如提供个性化练习，提高反馈效率？','安|对，但学习者仍要保持判断力，避免形成过度依赖。','林|技术能做什么和应该做什么，是两个不同的问题。'],grammar:{name:'与其说……不如说……',pattern:'与其说 + 表面判断，不如说 + 更准确判断',explain:'用于修正前一种说法，并提出说话人认为更准确的解释。',examples:['与其说它取代老师，不如说它改变了老师的角色。','与其说他失败了，不如说他正在积累经验。'],wrong:'与其说它取代老师，所以说它改变角色。'},listening:{q:'安认为学习者要注意什么？',audio:'学习者仍要保持判断力，避免形成过度依赖。',opts:['完全不用技术','保持判断力','只追求速度'],ans:1},shadowing:'与其说人工智能会取代老师，不如说它正在改变学习方式。',quiz:{q:'与其说他失败了，___ 他正在积累经验。',opts:['不如说','即使说','然而说'],ans:0,fb:'修正为更准确的判断，用“不如说”。'}}),
  makeUpperLesson({id:'QH-052',level:'HSK 6',title:'城市更新不能只看速度',scene:'评价公共建设',vocab:['更新','保留','居民','社区','功能','历史','协调','利益'],dialogue:['安|这片老街很快就要重新建设了。','林|城市更新不能只看速度，还要考虑居民的生活。','安|旧建筑是不是都应该保留？','林|不一定，但历史价值、社区功能和现实需求需要协调。','安|真正好的更新应该让不同群体都能受益。'],grammar:{name:'不能只……还要……',pattern:'不能只 + 单一标准，还要 + 其他因素',explain:'这一结构否定片面的判断，并补充必须同时考虑的因素。',examples:['城市更新不能只看速度，还要考虑居民生活。','评价学习不能只看分数，还要看能力变化。'],wrong:'城市更新不能只看速度，但是不用考虑居民。'},listening:{q:'城市更新需要协调哪些方面？',audio:'历史价值、社区功能和现实需求需要协调。',opts:['只有建设速度','历史、社区与现实需求','只考虑游客'],ans:1},shadowing:'城市更新不能只看速度，还要协调不同群体的利益。',quiz:{q:'评价学习不能只看分数，___ 看能力变化。',opts:['还要','反而不','于是'],ans:0,fb:'补充另一个必须考虑的因素，用“还要”。'}}),
  makeUpperLesson({id:'QH-053',level:'HSK 6',title:'面对分歧，如何达成共识',scene:'进行协商与讨论',vocab:['分歧','共识','协商','妥协','原则','立场','倾听','方案'],dialogue:['林|双方的立场差别这么大，还能达成共识吗？','安|有分歧并不意味着无法合作，关键是先确认共同目标。','林|那是不是双方都必须妥协？','安|可以调整方案，但原则问题需要说清楚，同时认真倾听对方。','林|共识不是消除所有差异，而是找到能继续合作的基础。'],grammar:{name:'并不意味着……',pattern:'事实 A + 并不意味着 + 必然结论 B',explain:'这一结构否定从某个事实直接推出的绝对结论，适合严谨论证。',examples:['有分歧并不意味着无法合作。','价格高并不意味着质量一定好。'],wrong:'有分歧并不所以无法合作。'},listening:{q:'达成共识的第一步是什么？',audio:'关键是先确认共同目标。',opts:['立刻放弃原则','先确认共同目标','避免倾听对方'],ans:1},shadowing:'有分歧并不意味着无法合作，关键是找到共同目标。',quiz:{q:'价格高并不 ___ 质量一定好。',opts:['意味着','意思着','表示了着'],ans:0,fb:'否定必然推论，常说“并不意味着”。'}}),
  makeUpperLesson({id:'QH-054',level:'HSK 6',title:'信息越多，判断就越容易吗？',scene:'反思信息与判断',vocab:['判断','筛选','来源','可靠','误导','证据','结论','复杂'],dialogue:['安|现在信息这么丰富，做判断应该更容易了吧？','林|未必。信息越多，筛选可靠来源反而越重要。','安|只看很多人的共同观点不够吗？','林|人数不能代替证据，还要检查信息从哪里来。','安|看来复杂问题往往需要暂时保留结论。'],grammar:{name:'未必；反而',pattern:'看似合理的判断 + 未必成立；实际情况反而……',explain:'“未必”表示不一定；“反而”引出与预期相反的情况。',examples:['信息多未必更容易判断。','资料增加以后，筛选反而更重要。'],wrong:'信息多未必所以更容易判断。'},listening:{q:'林认为人数能代替什么吗？',audio:'人数不能代替证据，还要检查信息从哪里来。',opts:['能代替证据','不能代替证据','能代替来源'],ans:1},shadowing:'信息越多未必越容易判断，筛选可靠来源反而更重要。',quiz:{q:'价格便宜 ___ 质量不好。',opts:['未必','必定未','反而一定'],ans:0,fb:'表示“不一定”可以用“未必”。'}}),
  makeUpperLesson({id:'QH-055',level:'HSK 6',title:'传统文化如何走向当代',scene:'讨论传承与创新',vocab:['传统','当代','传承','创新','形式','核心','观众','脱离'],dialogue:['林|传统文化要吸引年轻人，是不是应该变得更现代？','安|形式可以创新，但不能脱离文化的核心。','林|怎样判断创新是不是合适？','安|既要让当代观众理解，也要尊重传统本身的逻辑。','林|真正的传承不是重复过去，而是让它继续产生意义。'],grammar:{name:'既要……也要……',pattern:'既要 + 目标一，也要 + 目标二',explain:'用于强调两个目标或原则需要同时兼顾。',examples:['既要让观众理解，也要尊重传统逻辑。','发展既要讲效率，也要保证质量。'],wrong:'既要让观众理解，所以不要尊重传统。'},listening:{q:'安认为创新要满足哪两个条件？',audio:'既要让当代观众理解，也要尊重传统本身的逻辑。',opts:['只追求流行','理解当代并尊重传统','完全重复过去'],ans:1},shadowing:'传统文化的创新既要面向当代，也要尊重自身的核心。',quiz:{q:'发展既要讲效率，___ 保证质量。',opts:['也要','却不','因此只'],ans:0,fb:'两个目标都要兼顾，用“也要”。'}}),
  makeUpperLesson({id:'QH-056',level:'HSK 6',title:'压力有时也能成为动力',scene:'分析压力的双重作用',vocab:['压力','动力','适度','承受','长期','激发','消耗','恢复'],dialogue:['安|我总觉得压力完全是坏事。','林|压力看似让人不舒服，适度时却可能激发动力。','安|那为什么长期压力会让人疲惫？','林|因为承受压力也会消耗精力，如果得不到恢复，就会影响健康。','安|所以问题不只是有没有压力，还包括能不能管理它。'],grammar:{name:'看似……，实则/却……',pattern:'看似 + 表面现象，实则/却 + 深层情况',explain:'用于对比表面印象与更深入的事实，常见于分析性表达。',examples:['压力看似是负担，适度时却能成为动力。','这个办法看似简单，实则需要长期训练。'],wrong:'压力看似是负担，所以表面实则一样。'},listening:{q:'长期压力为什么会影响健康？',audio:'承受压力会消耗精力，如果得不到恢复，就会影响健康。',opts:['总能激发动力','会持续消耗精力','让人立刻休息'],ans:1},shadowing:'压力看似只是负担，适度时却也可能成为动力。',quiz:{q:'这个办法看似简单，___ 需要长期训练。',opts:['实则','只要','以免'],ans:0,fb:'表面与实际不同，可以用“实则”。'}}),
  makeUpperLesson({id:'QH-057',level:'HSK 6',title:'个人选择与公共责任',scene:'讨论自由与责任',vocab:['责任','公共','自由','边界','承担','后果','权利','影响'],dialogue:['林|个人有选择生活方式的自由，别人不应该干涉。','安|自由很重要，但选择也可能影响公共利益。','林|那自由的边界应该由谁决定？','安|关键并非限制个人，而是明确谁来承担行为造成的后果。','林|权利和责任需要放在同一个框架里讨论。'],grammar:{name:'并非……而是……',pattern:'并非 + 被否定的解释，而是 + 真正重点',explain:'用于纠正焦点，明确说话人真正想强调的内容。',examples:['关键并非限制个人，而是明确责任。','问题并非没有资源，而是缺少合作。'],wrong:'关键并非限制个人，所以而是明确责任。'},listening:{q:'安认为讨论的关键是什么？',audio:'关键并非限制个人，而是明确谁来承担行为造成的后果。',opts:['取消所有自由','明确后果由谁承担','避免讨论责任'],ans:1},shadowing:'关键并非限制个人选择，而是明确选择带来的公共责任。',quiz:{q:'问题并非没有资源，___ 缺少合作。',opts:['而是','而且','于是'],ans:0,fb:'纠正真正原因，用“并非……而是……”。'}}),
  makeUpperLesson({id:'QH-058',level:'HSK 6',title:'数据背后的人',scene:'理解统计与现实生活',vocab:['统计','平均','个体','差异','指标','反映','掩盖','处境'],dialogue:['安|报告显示平均收入提高了，说明大家生活都变好了吗？','林|平均数字能反映趋势，却可能掩盖个体之间的差异。','安|那我们应该怎样看这份数据？','林|值得注意的是，同一个指标背后可能有完全不同的生活处境。','安|数据很重要，但不能让真实的人从分析里消失。'],grammar:{name:'值得注意的是……',pattern:'值得注意的是 + 需要特别关注的信息',explain:'用于正式地引出容易被忽略、但对理解结论很重要的内容。',examples:['值得注意的是，平均数可能掩盖个体差异。','值得注意的是，样本规模仍然有限。'],wrong:'值得注意的是于平均数掩盖差异。'},listening:{q:'平均数字可能掩盖什么？',audio:'平均数字能反映趋势，却可能掩盖个体之间的差异。',opts:['统计方法','个体差异','报告标题'],ans:1},shadowing:'值得注意的是，统计数字背后可能是完全不同的个人处境。',quiz:{q:'___ ，样本规模仍然有限。',opts:['值得注意的是','只要注意','由于值得'],ans:0,fb:'正式引出重要限制时，可用“值得注意的是”。'}}),
  makeUpperLesson({id:'QH-059',level:'HSK 6',title:'当计划赶不上变化',scene:'复盘项目调整',vocab:['变化','调整','假设','灵活','偏差','应对','目标','路径'],dialogue:['林|原来的计划几乎都没按时完成，是不是计划失败了？','安|与其说计划失败，不如说最初的假设发生了变化。','林|那是不是计划没有意义？','安|计划让我们看见偏差，真正重要的是及时调整路径。','林|保持目标稳定，同时对方法保持灵活。'],grammar:{name:'与其说……不如说……',pattern:'与其说 + 简单结论，不如说 + 更准确解释',explain:'在复杂议题中，用这一结构避免过度简单的判断。',examples:['与其说计划失败，不如说条件发生了变化。','与其说他固执，不如说他非常重视原则。'],wrong:'与其说计划失败，但是不如条件变化。'},listening:{q:'安认为计划最重要的作用是什么？',audio:'计划让我们看见偏差，真正重要的是及时调整路径。',opts:['保证永远不变','帮助发现偏差并调整','取消最终目标'],ans:1},shadowing:'与其说计划失败，不如说我们需要根据变化调整路径。',quiz:{q:'与其说他固执，___ 他非常重视原则。',opts:['不如说','所以说','虽然说'],ans:0,fb:'用更准确的解释替代简单评价，用“不如说”。'}}),
  makeUpperLesson({id:'QH-060',level:'HSK 6',title:'什么才是真正的效率',scene:'重新定义工作效率',vocab:['效率','产出','价值','重复','优先','衡量','投入','归根结底'],dialogue:['安|我每天完成很多任务，为什么还是觉得效率不高？','林|任务数量不等于有效产出，你完成的事情真的重要吗？','安|有些只是重复处理，并没有创造多少价值。','林|归根结底，效率是把有限投入用在优先事项上。','安|看来我需要重新衡量任务，而不是把时间排得更满。'],grammar:{name:'归根结底',pattern:'分析若干因素后，归根结底 + 核心结论',explain:'“归根结底”用于总结复杂讨论，指出最根本的原因或判断。',examples:['归根结底，效率取决于优先顺序。','归根结底，学习需要主动投入。'],wrong:'归根结底因为所以效率优先顺序。'},listening:{q:'林怎样定义效率？',audio:'效率是把有限投入用在优先事项上。',opts:['完成最多任务','把投入用于优先事项','让日程没有空白'],ans:1},shadowing:'归根结底，真正的效率是把有限投入用在最重要的事情上。',quiz:{q:'___ ，学习需要主动投入。',opts:['归根结底','虽然结底','只要根本'],ans:0,fb:'总结最核心的结论，可以用“归根结底”。'}})
];

lessons.push(...upperLessons);
